components.css:
.ds-btn-primary {
  background: #10B981;
  color: #000000;
  padding: 18px 42px;
  border-radius: 999px;
  font-family: 'Inter', 'SF Pro Display', sans-serif;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.01em;
  border: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 12px;
  box-shadow: 0 0 40px rgba(16, 185, 129, 0.4), inset 0 2px 4px rgba(255,255,255,0.2);
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-btn-primary:hover {
  background: #34D399;
  transform: translateY(-2px);
  box-shadow: 0 0 60px rgba(16, 185, 129, 0.6), inset 0 2px 4px rgba(255,255,255,0.3);
}
.ds-btn-primary:active {
  background: #059669;
  transform: translateY(0);
  box-shadow: 0 0 20px rgba(16, 185, 129, 0.3);
}
.ds-btn-primary:focus-visible {
  outline: 2px solid #10B981;
  outline-offset: 4px;
}

.ds-btn-ghost {
  background: rgba(255,255,255,0.03);
  color: #ffffff;
  padding: 18px 42px;
  border-radius: 999px;
  font-family: 'Inter', 'SF Pro Display', sans-serif;
  font-size: 18px;
  font-weight: 500;
  letter-spacing: -0.01em;
  border: 1px solid rgba(255,255,255,0.25);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-btn-ghost:hover {
  background: rgba(255,255,255,0.08);
  border-color: rgba(255,255,255,0.4);
  transform: translateY(-2px);
}
.ds-btn-ghost:focus-visible {
  outline: 2px solid #10B981;
  outline-offset: 4px;
}

.ds-card {
  background: #0a0a0a;
  color: #ffffff;
  padding: 32px;
  border-radius: 20px;
  border: 1px solid rgba(255,255,255,0.08);
  box-shadow: rgba(0,0,0,0.4) 0px 8px 32px 0px;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-card-label {
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: rgba(255,255,255,0.7);
  display: block;
  margin-bottom: 16px;
}
.ds-card-content {
  color: rgba(255,255,255,0.4);
  font-size: 14px;
}

.ds-card-selected {
  background: linear-gradient(135deg, rgba(16,185,129,0.15) 0%, rgba(16,185,129,0.02) 100%);
  color: #ffffff;
  padding: 20px;
  border-radius: 20px;
  border: 1px solid rgba(16,185,129,0.4);
  box-shadow: 0 10px 30px rgba(16,185,129,0.15);
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  cursor: pointer;
  position: relative;
  overflow: hidden;
}
.ds-card-selected::before {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  width: 150px;
  height: 150px;
  background: radial-gradient(circle, rgba(16,185,129,0.2) 0%, transparent 70%);
  pointer-events: none;
}
.ds-card-selected-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 16px;
}
.ds-card-badge {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: #fbbf24;
  color: #000;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
}
.ds-card-check {
  width: 20px;
  height: 20px;
}
.ds-card-value {
  font-family: 'JetBrains Mono', monospace;
  font-size: 20px;
  color: #10B981;
}

.ds-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.85);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px;
  z-index: 50;
}
.ds-modal {
  background: rgba(23,23,23,0.95);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 24px;
  box-shadow: 0 20px 60px rgba(0,0,0,0.5), 0 0 100px rgba(16,185,129,0.1);
  padding: 40px;
  max-width: 560px;
  width: 100%;
  position: relative;
  overflow: hidden;
}
.ds-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 32px;
}
.ds-modal-header h3 {
  font-size: 40px;
  font-weight: 700;
  color: #ffffff;
}
.ds-modal-close {
  padding: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,0.05);
  color: rgba(255,255,255,0.7);
  border: none;
  cursor: pointer;
  transition: all 0.15s ease;
}
.ds-modal-close:hover {
  background: rgba(255,255,255,0.15);
  color: #ffffff;
}
.ds-modal-body {
  color: rgba(255,255,255,0.7);
  font-size: 17px;
}

.ds-status-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px;
  border-radius: 999px;
  background: rgba(16,185,129,0.15);
  color: #34D399;
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  border: 1px solid rgba(16,185,129,0.2);
}
.ds-status-badge-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #10B981;
  animation: ds-pulse 2s ease-in-out infinite;
}
@keyframes ds-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

.ds-input {
  width: 100%;
  background: #000000;
  color: rgba(255,255,255,0.85);
  padding: 48px;
  border-radius: 20px;
  border: 1px solid rgba(255,255,255,0.05);
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-size: 24px;
  line-height: 1.6;
  outline: none;
  transition: border-color 0.3s ease, box-shadow 0.3s ease;
}
.ds-input::placeholder {
  color: rgba(255,255,255,0.2);
}
.ds-input:focus {
  border-color: rgba(16,185,129,0.5);
  box-shadow: 0 0 20px rgba(16,185,129,0.1);
}
